GO

ALTER TRIGGER tD_ICCostDetail_CostFex on ICCostDetail  
 For Delete As  
Begin  
 declare  @numrows int,  
          @nullcnt int,  
          @validcnt int,  
          @insStockDetailID u_ID,  
          @errno   int,  
          @errmsg  varchar(255),  
   	  @cosflag varchar(20)  
-- [Ane:25/08/2551][W20080807-004=>ถ้าคำนวณต้นทุนแบบรวมสาขาให้มอง icoption จากสำนักงานใหญ่]
  select @numrows = @@rowcount  
 -- Option การคำนวณแยกตามคลัง(@cosflag = Y)หรือรวมคลัง(@cosflag = N)  
 set @cosflag = ( Select top 1 ICOption.CostInveFlag From ICOption,Deleted Where ICOption.BrchID =Deleted.brchid)  
 -- ถ้าคำนวณแบบรวมสาขา ให้มอง icoption จากสาขาสำนักงานใหญ่
 if ((@cosflag = '')  or (@cosflag  is null) )  
 begin
      select @cosflag =ICOption.CostInveFlag From ICOption,EMBrch Where (ICOption.BrchID =EMBrch.brchid) and (EMBrch.Headoffice   = 'Y')  
 end

 IF(@cosflag = 'N')  
 Begin  
  update  icstockdetail  
  set  icstockdetail.costflag = 'N'  
  from icstockdetail ,Deleted  
  where (icstockdetail.stockdetailid = Deleted.stockdetailid) and  
   (icstockdetail.goodid = Deleted.Goodid )   and   
   (Deleted.stockflag in (1,-1))and
   (icstockdetail.costflag = 'Y') 
 End  
 Else  
 Begin  
  update  icstockdetail  
  set  icstockdetail.costflag = 'N'  
  from icstockdetail ,Deleted  
  where (icstockdetail.stockdetailid = Deleted.stockdetailid) and  
   (icstockdetail.goodid = Deleted.Goodid )  and 
   (Deleted.stockflag in (1,-1))and 
   (icstockdetail.costflag = 'Y') and   
   (icstockdetail.InveID = Deleted.InveID)
 End  
  return  
error:  
    raiserror(@errmsg, 16, 1)  
    rollback transaction  
End   

GO
PRINT 'fixed dbo.tD_ICCostDetail_CostFex';
GO

