-- ===== dbo.tD_ICStockCost_ex =====
GO
/***********************************************************
	Trigger Delete
***********************************************************/
ALTER TRIGGER tD_ICStockCost_ex on dbo.ICStockCost
  for DELETE
  as
 begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insStockDetailID u_ID,
           @errno   int,
           @errmsg  varchar(255)
  select @numrows = @@rowcount
  update ICStockDetail
  set ResvAmnt2 = (select Convert(decimal(19,4),isnull(Sum(Case ICStockCost.StockFlag 
		    When 1 Then Convert(decimal(19,4),isnull(ICStockCost.ReceAmnt,0))
		    	   Else Convert(decimal(19,4),isnull(ICStockCost.PayAmnt,0))End),0),0)
		    from  ICStockCost,deleted
		    where (ICStockCost.GoodID = deleted.GoodID) and 
			(ICStockCost.BrchID = deleted.BrchID) and 
			(ICStockCost.DocuType = deleted.DocuType) and 
			(ICStockCost.DocuTypeCode = deleted.DocuTypeCode) and 
			(ICStockCost.DocuID = deleted.DocuID) and
			(ICStockCost.ListNo = deleted.ListNo) and
			(ICStockCost.StockDetailID <> deleted.StockDetailID))
  from 	deleted
  where (ICStockDetail.GoodID = deleted.GoodID) and 
	(ICStockDetail.BrchID = deleted.BrchID) and 
	(ICStockDetail.DocuType = deleted.DocuType) and 
	(ICStockDetail.DocuTypeCode = deleted.DocuTypeCode) and 
	(ICStockDetail.DocuID = deleted.DocuID) and
	(ICStockDetail.ListNo = deleted.ListNo) and
	(ICStockDetail.StockDetailID = deleted.StockDetailID)

  return
error:
    raiserror(@errmsg, 16, 1)
    rollback transaction
end

GO
PRINT 'fixed dbo.tD_ICStockCost_ex';
GO

