      select ICStockSerialDetail.StockDetailID from deleted,ICStockSerialDetail  
      where  
        /*  %JoinFKPK(ICStockSerialDetail,deleted," = "," and") */  
        ICStockSerialDetail.StockDetailID = deleted.StockDetailID  
    )  
    begin  
      select @errno  = 30001,  
             @errmsg = 'Cannot DELETE ICStockDetail because ICStockSerialDetail exists.'  
      goto error  
    end     
  
  return  
error:  
    raiserror(@errmsg, 16, 1)  
    rollback transaction  
end  

GO
PRINT 'fixed dbo.tD_ICStockDetail';
GO

-- ===== dbo.tD_ICStockDetail_ex =====
GO

 ALTER TRIGGER tD_ICStockDetail_ex on ICStockDetail            
  for DELETE            
  as            
begin            
  declare  @numrows int,            
           @nullcnt int,            
           @validcnt int,            
           @insStockDetailID u_ID,            
           @errno   int,            
           @errmsg  varchar(255),            
           @cosflag varchar(20),            
           @havebrch int  ,          
           @count int          
          
-- แก้ไขโดยพี่ตุ้มในส่วนของการเลือกปรับปรุง costflag และลบข้อมูล สำหรับการโอนทั้งในกรณี          
-- แยกคลัง หรือรวมคลังสินค้า [09-03-2548] [nop]          
-- [Ane:25/08/2551][W20080807-004=>ปรับการ upate ICstock ออกเพราะทำให้การ delete , update icstockdetail ตอนที่บันทึกรายการและคำนวณต้นทุนช้าถ้าเบสที่มีขนาดใหญ่มากๆ]      
select @numrows = @@rowcount            
-- Option การคำนวณแยกตามคลัง(@cosflag = Y)หรือรวมคลัง(@cosflag = N)            
set @cosflag = (select top 1 ICOption.CostInveFlag From ICOption,deleted Where ICOption.BrchID =deleted.brchid)      
-- Option สาขาของ IC ว่าเป็นรวม(@havebrch = 0)หรือแยกสาขา(@havebrch = สาขาที่ทำการ)            
set @havebrch = (Select  top 1 (case when EmOptionEXT.havebrch = 'N'then 0 else deleted.Brchid end )From EmOptionEXT,deleted Where EmOptionEXT.systemid =( Select smsystem.systemid from smsystem where smsystem.systemcode ='IC' ) And EmOptionEXT.brchid = deleted.brchid )      
      
-- นับจำนวนของเอกสารรายการโอน โดยระบุว่าเป็นรายการโอนหรือไม่ในส่วนของ in          
select @count = count(ICStockDetail.Stockdetailid)     
from  ICStockDetail , deleted        
where(ICStockDetail.GoodID = deleted.GoodID )      
 and  ICStockDetail.docutype in (109,704,710,719,720,2001)     
 and (ICStockDetail.Brchid = @havebrch or 0 = @havebrch )      
 and (ICStockDetail.DocuDate >= deleted.DocuDate )      
        
 IF(@cosflag = 'N')             
 Begin            
  -- การทำงานของการคำนวณรวมตามคลัง            
  update  ICStockDetail            
  set     ICStockDetail.CostFlag = 'N'       
  from    ICStockDetail,deleted            
  where  (ICStockDetail.GoodID = deleted.GoodID)              
   and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )              
   and(ICStockDetail.DocuDate >= deleted.DocuDate)              
   and(ICStockDetail.CostFlag = 'Y')            
   and(ICStockDetail.StockDetailID <> deleted.StockDetailID)            
             
  delete  ICCostDetail            
  from    ICCostDetail,deleted            
  where  (ICCostDetail.GoodID = deleted.GoodID)              
      and(ICCostDetail.Brchid = @havebrch or 0 = @havebrch )          
      and(ICCostDetail.DocuDate >= deleted.DocuDate)            
 End    
 Else            
 Begin            
 -- เป็นการโอนรายการสินค้า           
 IF(@count > 0)          
 begin          
  -- การทำงานของการคำนวณแยกตามคลัง  กรณีโอนสินค้า ตัดส่วนของการทำงานของ invetory ออกไป          
   update  ICStockDetail            
   set     ICStockDetail.CostFlag = 'N'            
   from    ICStockDetail,deleted            
   where  (ICStockDetail.GoodID = deleted.GoodID)              
   and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )              
   and(ICStockDetail.DocuDate >= deleted.DocuDate)              
   and(ICStockDetail.CostFlag = 'Y')             
   and(ICStockDetail.StockDetailID <> deleted.StockDetailID)            
              
  delete ICCostDetail            
   from  ICCostDetail,deleted            
   where(ICCostDetail.GoodID = deleted.GoodID)              
     and(ICCostDetail.Brchid = @havebrch or 0 = @havebrch )
     and(ICCostDetail.DocuDate >= deleted.DocuDate)            
 end    
 else          
 begin          
  -- การทำงานของการคำนวณแยกตามคลัง  กรณีปกติ          
   update  ICStockDetail            
   set     ICStockDetail.CostFlag = 'N'            
   from    ICStockDetail,deleted            
   where  (ICStockDetail.GoodID = deleted.GoodID)              
   and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )            
   and(ICStockDetail.DocuDate >= deleted.DocuDate)              
   and(ICStockDetail.CostFlag = 'Y')             
   and(ICStockDetail.StockDetailID <> deleted.StockDetailID)      
   and(ICStockDetail.InveID = deleted.InveID)      
              
  delete  ICCostDetail            
  from    ICCostDetail,deleted            
  where  (ICCostDetail.GoodID = deleted.GoodID)             
    and(ICCostDetail.Brchid = @havebrch or 0 = @havebrch )
    and(ICCostDetail.DocuDate >= deleted.DocuDate)       
    and(ICCostDetail.InveID = deleted.InveID)      
 end    
 End    
  return            
error:            
    raiserror(@errmsg, 16, 1)            
    rollback transaction            
end

GO
PRINT 'fixed dbo.tD_ICStockDetail_ex';
GO

