ALTER TRIGGER tD_JCCloseHD on JCCloseHD
  for DELETE
  as
/* ERwin Builtin Wed May 07 22:19:47 2003 */
/* DELETE trigger on JCCloseHD */
/* default body for tD_JCCloseHD */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insJCCloseID u_ID,
