-- ===== dbo.tD_WHStockSerialDetail_ex =====
GO

ALTER TRIGGER [tD_WHStockSerialDetail_ex] on [dbo].[WHStockSerialDetail] For Delete AS        
Begin        
 Declare 
  @numrows  int,        
  @errmsg   varchar(255),        
  @errno    int,         
  @StockSerialDetailID u_id ,        
  @stockflag int ,  /*ตรวจสอบ flow : 1 = ปกติ   0 = po ใบรับสินค้า , No stock effect*/          
  @docutype  u_globalflag

  Select @numrows = @@rowcount
   
  Select @StockSerialDetailID = Deleted.StockSerialDetailID ,    
            @stockflag = isnull(Deleted.stockflag,1) ,
	     @docutype = docutype 
  From Deleted
   
 if @numrows > 0   
 Begin
	/* stockflag <> 0  ถึงจะ update serial ล่าสุด*/    
	update icstockserial set        
		icstockserial.whdocutype=WHstockserialdetail.docutype,        
		icstockserial.whdocutypecode=WHstockserialdetail.docutypecode,        
		icstockserial.whdocuid=WHstockserialdetail.docuid,        
		icstockserial.whlistno=WHstockserialdetail.listno,        
		icstockserial.whserialflag=isnull(WHstockserialdetail.serialflag,'N'),        
		icstockserial.whlistnoref=WHstockserialdetail.seriallistno,        
		icstockserial.whInveID=WHstockserialdetail.InveID,        
		icstockserial.whLocaID=WHstockserialdetail.LocaID,
		icstockserial.whBrchID=WHstockserialdetail.BrchID,        
		icstockserial.whStockSerialDetailID=WHstockserialdetail.StockSerialDetailID,        
		icstockserial.whPrevDetailID=WHstockserialdetail.PrevDetailID,        
		icstockserial.whLastserialflag= isnull((select dt1.serialflag from WHstockserialdetail dt1 where  dt1.StockSerialDetailID = WHstockserialdetail.PrevDetailID),'N')  
	from Deleted,icstockserial   
	left outer join WHstockserialdetail on icstockserial.whprevdetailid=WHstockserialdetail.stockserialdetailid
	where icstockserial.whstockserialdetailid=Deleted.StockSerialDetailID  
	--and Deleted.stockflag = 1
	
	Update WHstockserialdetail  Set
		Prevdetailid = Null , flag = 1
	from Deleted , WHstockserialdetail  
	Where Deleted.Stockserialdetailid = WHstockserialdetail.Prevdetailid
	and Deleted.goodid = WHstockserialdetail.goodid
	and Deleted.lotno = WHstockserialdetail.lotno
	and Deleted.serialno = WHstockserialdetail.serialno

	if (@docutype = 1712) 
	 Begin
		update icstockserial set      
			icstockserial.whdocutype = WHstockserialdetail.docutype,      
			icstockserial.whdocutypecode = WHstockserialdetail.docutypecode,      
			icstockserial.whdocuid = WHstockserialdetail.docuid,      
			icstockserial.whlistno = WHstockserialdetail.listno,      
			icstockserial.whserialflag = isnull(WHstockserialdetail.serialflag,'N'),      
			icstockserial.whlistnoref	 = WHstockserialdetail.seriallistno,      
			icstockserial.whInveID = WHstockserialdetail.InveID,      
			icstockserial.whLocaID = WHstockserialdetail.LocaID,
			icstockserial.whBrchID = WHstockserialdetail.BrchID,      
			icstockserial.whStockSerialDetailID = WHstockserialdetail.StockSerialDetailID,      
			icstockserial.whPrevDetailID = WHstockserialdetail.PrevDetailID,      
			icstockserial.whLastserialflag = isnull((select dt1.serialflag from WHstockserialdetail dt1      
		where  dt1.StockSerialDetailID = icstockserial.whstockserialdetailid),'N')
		from icstockserial ,WHstockserialdetail , Deleted
		where Deleted.refflag = 'D'
		and WHstockserialdetail.stockserialdetailid = Deleted.Prevdetailid	  
		and ( icstockserial.whstockserialdetailid = WHstockserialdetail.prevdetailid 
		or icstockserial.whstockserialdetailid is null) /*กรณีอนุมัติสั่งซื้อที่ไม่อนุมัติ Stockserialdetaiid จะเป็น null*/
		and icstockserial.goodid = WHstockserialdetail.goodid
		and icstockserial.lotno = WHstockserialdetail.lotno
		and icstockserial.Serialno = WHstockserialdetail.Serialno
	End
 End 

 Return        
    error:        
    raiserror(@errmsg, 16, 1)        
    rollback transaction        
         
End

GO
PRINT 'fixed dbo.tD_WHStockSerialDetail_ex';
GO

