ALTER TRIGGER tI_ADClearDT on ADClearDT
  for INSERT
  as
/* ERwin Builtin Fri Jan 31 21:56:01 2003 */
/* INSERT trigger on ADClearDT */
/* default body for tI_ADClearDT */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insADClearID u_ID, 
           @insListNo u_ListNo,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
/* ERwin Builtin Fri Jan 31 21:56:01 2003 */
  /* EMExpn R/1969 ADClearDT ON CHILD INSERT RESTRICT */
  if
    /* %ChildFK(" or",update) */
    update(ExpnID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMExpn
        where
          /* %JoinFKPK(inserted,EMExpn) */
          inserted.ExpnID = EMExpn.ExpnID
    /* %NotnullFK(inserted," is null","select @nullcnt = count(*) from inserted where"," and") */
    select @nullcnt = count(*) from inserted where
      inserted.ExpnID is null
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30002,
             @errmsg = 'Cannot INSERT ADClearDT because EMExpn does not exist.'
      goto error
    end
  end

/* ERwin Builtin Fri Jan 31 21:56:01 2003 */
