      from inserted,EMDept
        where
          /* %JoinFKPK(inserted,EMDept) */
          inserted.DeptID = EMDept.DeptID
    /* %NotnullFK(inserted," is null","select @nullcnt = count(*) from inserted where"," and") */
    select @nullcnt = count(*) from inserted where
      inserted.DeptID is null
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30002,
             @errmsg = 'Cannot INSERT ADClearDT because EMDept does not exist.'
      goto error
    end
  end

/* ERwin Builtin Fri Jan 31 21:56:01 2003 */
  /* EMJob R/1967 ADClearDT ON CHILD INSERT RESTRICT */
