ALTER TRIGGER tI_ICCostDetail_costFex on ICCostDetail  
 For Insert As  
Begin  
 declare  @numrows int,  
          @nullcnt int,  
          @validcnt int,  
          @insStockDetailID u_ID,  
          @errno   int,  
          @errmsg  varchar(255),  
   @cosflag varchar(20)  
-- [Ane:25/08/2551][W20080807-004=>ถ้าคำนวณต้นทุนแบบรวมสาขาให้มอง icoption จากสำนักงานใหญ่]    
  select @numrows = @@rowcount  
 -- Option การคำนวณแยกตามคลัง(@cosflag = Y)หรือรวมคลัง(@cosflag = N)  
 set @cosflag = ( Select top 1 ICOption.CostInveFlag From ICOption,inserted Where ICOption.BrchID =inserted.brchid)  
 -- ถ้าคำนวณแบบรวมสาขา ให้มอง icoption จากสาขาสำนักงานใหญ่
 if ((@cosflag = '')  or (@cosflag  is null) )  
 begin
      select @cosflag =ICOption.CostInveFlag From ICOption,EMBrch Where (ICOption.BrchID =EMBrch.brchid) and (EMBrch.Headoffice   = 'Y')  
 end
   
 IF(@cosflag = 'N')  
 Begin  
  update  icstockdetail  
  set  icstockdetail.costflag = 'Y'  
  from icstockdetail ,inserted  
  where (icstockdetail.stockdetailid = inserted.stockdetailid) and  
   (icstockdetail.goodid = inserted.Goodid )and   
   (inserted.stockflag in (1,-1))and
   (icstockdetail.costflag = 'N')
 End  
 Else  
 Begin  
  update  icstockdetail  
  set  icstockdetail.costflag = 'Y'  
  from icstockdetail ,inserted  
  where (icstockdetail.stockdetailid = inserted.stockdetailid) and  
   (icstockdetail.goodid = inserted.Goodid )and  
   (inserted.stockflag in (1,-1))and
   (icstockdetail.costflag = 'N') and   
   (icstockdetail.InveID = inserted.InveID) 
 End  
  return  
error:  
    raiserror(@errmsg, 16, 1)  
    rollback transaction  
End   

GO
PRINT 'fixed dbo.tI_ICCostDetail_costFex';
GO

