-- ===== dbo.tI_ICStockCost_ex =====
GO
/***********************************************************
	Trigger Insert
***********************************************************/
ALTER TRIGGER tI_ICStockCost_ex on dbo.ICStockCost
  for INSERT
  as
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insStockDetailID u_ID,
           @errno   int,
           @errmsg  varchar(255) ,
	   @goodcostflag varchar(1)

  select @numrows = @@rowcount
  select @goodcostflag = emgood.CostEstimate from emgood, inserted where emgood.goodid = inserted.goodid

  /*Average*/
  if (@goodcostflag = '1')
  begin
  -- สร้างตัวแปร และหาค่าให้กับตัวแปรนั้นๆ เพื่ือไปใช้งานของ FIFO,Average,Specific Lot และ Standard Cost
  declare
	@StockdetailID	u_id,
	@stockcostid 	u_id ,
	@docuid 	u_id , 
	@goodid 	u_id , 
	@brchid 	u_id ,
	@listno 	u_listno , 
	@docutype 	int ,
	@docutypecode 	varchar(1),
	@costamnt 	u_amnt,
	@costamntins	u_amnt,
	@sumcostamnt 	u_amnt,
	@stockflag	int
     select 
        @stockcostid = inserted.stockcostid ,
	@docutype    = inserted.docutype ,
	@docutypecode= inserted.docutypecode , 
	@docuid      = inserted.docuid , 
	@listno      = inserted.listno , 
	@goodid      = inserted.goodid , 
	@brchid      = inserted.brchid ,
	@StockdetailID = inserted.stockdetailid
     from inserted

  exec spu_icstockcost_Average @StockCostID,@docuid,@goodid,@brchid,@listno,@docutype,@docutypecode,@costamnt output	

  select @costamntins = Convert(decimal(19,4),isnull(Sum 
		  (Case inserted.StockFlag When 1
		   Then(Case When isnull(inserted.InQty,0)>= 0 and isnull(inserted.OutQty,0) >= 0 Then Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))
			     When isnull(inserted.InQty,0) < 0 and isnull(inserted.OutQty,0) < 0 Then 0
			     When isnull(inserted.InQty,0) < 0 and isnull(inserted.OutQty,0) >= 0 Then 
					Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))-(Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))-Convert(decimal(19,4),isnull(inserted.OutAmnt,0)))
			Else Convert(decimal(19,4),isnull(inserted.ReceAmnt,0)) End)
		   Else (Case When inserted.OutQty >= 0 
			 Then Convert(decimal(19,4),isnull(inserted.PayAmnt,0))
			 Else Convert(decimal(19,4),isnull(inserted.InAmnt,0)) End)
		   End),0),0)
  from	inserted
  where (inserted.GoodID = @goodid) and 
	(inserted.BrchID = @brchid) and 
	(inserted.DocuType= @docutype) and 
	(inserted.DocuTypeCode = @docutypecode) and 
	(inserted.DocuID = @docuid) and
	(inserted.ListNo = @listno) and
	(inserted.StockCostID = @stockcostid)  and
	(inserted.StockDetailID = @StockDetailID)

  select @sumcostamnt = @costamnt + @costamntins

  update ICStockDetail
  set 	ResvAmnt2 = @sumcostamnt
  from	ICStockDetail
  where (ICStockDetail.GoodID = @goodid) and 
	(ICStockDetail.BrchID = @brchid) and 
	(ICStockDetail.DocuType= @docutype) and 
	(ICStockDetail.DocuTypeCode = @docutypecode) and 
	(ICStockDetail.DocuID = @docuid) and
	(ICStockDetail.ListNo = @listno) and
	(ICStockDetail.StockDetailID = @StockDetailID)

  end

 /* FIFO*/
 if (@goodcostflag = '2')
  begin
     select 
        @stockcostid = inserted.stockcostid ,
	@docutype    = inserted.docutype ,
	@docutypecode= inserted.docutypecode , 
	@docuid      = inserted.docuid , 
	@listno      = inserted.listno , 
	@goodid      = inserted.goodid , 
	@brchid      = inserted.brchid ,
	@StockdetailID = inserted.stockdetailid
     from inserted

     -- หาต้นทุนของเอกสารที่เพิ่มหากมีการกระทำมากกว่า 1 รายการ
     exec spu_icstockcost_FIFO @stockcostid,@docutype,@docutypecode,@docuid,@listno,@goodid,@brchid,@costamnt output 

     select @costamntins =  Convert(decimal(19,4),isnull(Sum
		      (Case inserted.StockFlag When 1 
		      /*การรับเข้า*/	
		      Then (Case When (isnull(inserted.InQty,0) = 0) and (isnull(inserted.InAmnt,0) = 0)and
				      (isnull(inserted.OutQty,0)<> 0)and (isnull(inserted.OutAmnt,0) = 0)
				      Then 0  ---isnull(inserted.ReceAmnt,0)
				 When (isnull(inserted.OutQty,0) > 0)and(isnull(inserted.OutAmnt,0) > 0)
				      Then Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))
				 When (isnull(inserted.InQty,0) = 0)and (isnull(inserted.InAmnt,0) = 0)and
				      (isnull(inserted.OutQty,0) = 0)and (isnull(inserted.OutAmnt,0) = 0)		
				      Then 0-- -isnull(inserted.ReceAmnt,0)  	
			    Else 0 End)
		      /*การจ่ายออก*/
		      Else (Case When (isnull(inserted.InQty,0) > 0)and (isnull(inserted.InAmnt,0) > 0)and
				      (isnull(inserted.OutQty,0) = 0)and (isnull(inserted.OutAmnt,0) = 0)	
				      Then Convert(decimal(19,4),isnull(inserted.InAmnt,0))
 				When (isnull(inserted.InQty,0) = 0)and (isnull(inserted.InAmnt,0) = 0)and
				      (isnull(inserted.OutQty,0) = 0)and (isnull(inserted.OutAmnt,0) = 0)	
				      Then (Case  When isnull(inserted.Inqty,0) = 0 
							  Then 0 
							  Else (Convert(decimal(19,4),isnull(inserted.InAmnt,0))*
								Convert(decimal(19,4),isnull(inserted.payqty,0)))/
								Convert(decimal(19,4),isnull(inserted.Inqty,0))
						    End )
				 When (isnull(inserted.InQty,0) = 0)and (isnull(inserted.InAmnt,0) = 0)and
				      (isnull(inserted.OutQty,0) < 0)and (isnull(inserted.OutAmnt,0) = 0)	
				      Then 0
				 Else (Case  When isnull(inserted.Inqty,0) = 0 
							  Then 0 
							  Else (Convert(decimal(19,4),isnull(inserted.InAmnt,0))*
								Convert(decimal(19,4),isnull(inserted.payqty,0)))/
								Convert(decimal(19,4),isnull(inserted.Inqty,0))
						    End )
				End)
		      End),0),0)
     from inserted
     where (inserted.GoodID = @goodid) and 
	   (inserted.BrchID = @brchid) and 
	   (inserted.DocuType = @docutype) and 
	   (inserted.DocuTypeCode = @docutypecode) and 
	   (inserted.DocuID = @docuid) and
	   (inserted.ListNo = @listno) and
	   (inserted.StockCostID = @stockcostid)
  end 
 select @sumcostamnt = (@costamnt + @costamntins)
 
  update ICStockDetail	
  set ResvAmnt2 = @sumcostamnt
  from ICStockDetail
  where    (ICStockDetail.GoodID = @GoodID) and
	   (ICStockDetail.BrchID = @BrchID) and 
	   (ICStockDetail.DocuType = @DocuType) and 
	   (ICStockDetail.DocuTypeCode = @DocuTypeCode) and 
	   (ICStockDetail.DocuID = @DocuID) and
	   (ICStockDetail.ListNo = @ListNo) and
	   (ICStockDetail.StockdetailID = @StockdetailID)

  /*Specific Lot*/
  if (@goodcostflag = '3')
  begin
     declare @lotno varchar(255)
     select 
        @stockcostid = inserted.stockcostid ,
	@docutype    = inserted.docutype ,
	@docutypecode= inserted.docutypecode , 
	@docuid      = inserted.docuid , 
	@listno      = inserted.listno , 
	@goodid      = inserted.goodid , 
	@brchid      = inserted.brchid ,
	@lotno	     = inserted.lotno ,	
	@StockdetailID = inserted.stockdetailid
     from inserted

  exec spu_icstockcost_SpecLot @StockCostID,@docuid,@goodid,@brchid,@listno,@docutype,@docutypecode,@lotno,@costamnt output	

  select @costamntins =Convert(decimal(19,4),isnull(Sum
		  (Case inserted.StockFlag When 1 
		      /*การรับเข้า*/
		      Then (Case When (isnull(inserted.Outqty,0) <= 0)Then 0
				 Else Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))
			         End)
		      /*การจ่ายออก*/
		      Else 
			  Convert(decimal(19,4),isnull(inserted.PayAmnt,0))
		      End),0),0)

  from	inserted
  where (inserted.GoodID = @goodid) and 
	(inserted.BrchID = @brchid) and 
	(inserted.DocuType= @docutype) and 
	(inserted.DocuTypeCode = @docutypecode) and 
	(inserted.DocuID = @docuid) and
	(inserted.ListNo = @listno) and
	(inserted.LotNo = @lotno) and	
	(inserted.StockCostID = @stockcostid)  and
	(inserted.StockDetailID = @StockDetailID)

  select @sumcostamnt = @costamnt + @costamntins

  update ICStockDetail
  set 	ResvAmnt2 = @sumcostamnt
  from	ICStockDetail
  where (ICStockDetail.GoodID = @goodid) and 
	(ICStockDetail.BrchID = @brchid) and 
	(ICStockDetail.DocuType= @docutype) and 
	(ICStockDetail.DocuTypeCode = @docutypecode) and 
	(ICStockDetail.DocuID = @docuid) and
	(ICStockDetail.ListNo = @listno) and
	(ICStockDetail.StockDetailID = @StockDetailID)

  end

/*Standard Cost*/
  if (@goodcostflag = '5')
  begin

     select 
        @stockcostid = inserted.stockcostid ,
	@docutype    = inserted.docutype ,
	@docutypecode= inserted.docutypecode , 
	@docuid      = inserted.docuid , 
	@listno      = inserted.listno , 
	@goodid      = inserted.goodid , 
	@brchid      = inserted.brchid ,
	@StockdetailID = inserted.stockdetailid
     from inserted

  exec spu_icstockcost_StdCost @StockCostID,@docuid,@goodid,@brchid,@listno,@docutype,@docutypecode,@costamnt output	

  select @costamntins =Convert(decimal(19,4),isnull(Sum
			(Case inserted.StockFlag When 1 
				/*การรับเข้า*/
				Then (Case When /*รับแล้วติดลบ*/	
					   ((Isnull(inserted.Outqty,0) < 0)and isnull(inserted.ReceAmnt,0) > 0)Then
						Convert(decimal(19,4),isnull(inserted.PayAmnt,0))
					   When /*รับแล้ว ติดลบ เป็นไ่ม่ติดลบ*/	
					   (Isnull(inserted.InQty,0)< 0)and(Isnull(inserted.OutQty,0)> 0) Then
						(Convert(decimal(19,4),isnull(inserted.ReceQty,0))-
						 (Convert(decimal(19,4),isnull(inserted.ReceQty,0))-
						  Convert(decimal(19,4),isnull(inserted.OutQty,0))))*
						(Convert(decimal(19,4),isnull(inserted.ReceAmnt,0))/
						Convert(decimal(19,4),isnull(inserted.ReceQty,0)))
					   Else Convert(decimal(19,4),isnull(inserted.ReceAmnt,0)) End)
				/*การจ่ายออก*/
				Else
				   (Case When /*จ่ายแล้วมีการติดลบ*/
					 (isnull(inserted.InQty,0) > 0 and isnull(inserted.OutQty,0) < 0) Then 
						(Convert(decimal(19,4),isnull(inserted.InAmnt,0)))
					 When /*จ่ายแล้วไม่ติดลบ*/ 
					 (Isnull(inserted.InQty,0)> 0)and (Isnull(inserted.OutQty,0)> 0)Then
					     (Convert(decimal(19,4),isnull(inserted.PayAmnt,0)))
		 			 When /*จ่ายแล้วหมดพอดี*/
					 (Isnull(inserted.InQty,0)> 0)and (Isnull(inserted.OutQty,0)= 0 )Then
					     (Convert(decimal(19,4),isnull(inserted.PayAmnt,0)))	
					Else 0 End)
			 End),0),0)
  from	inserted
  where (inserted.GoodID = @goodid) and 
	(inserted.BrchID = @brchid) and 
	(inserted.DocuType= @docutype) and 
	(inserted.DocuTypeCode = @docutypecode) and 
	(inserted.DocuID = @docuid) and
	(inserted.ListNo = @listno) and
	(inserted.StockCostID = @stockcostid)  and
	(inserted.StockDetailID = @StockDetailID)

  select @sumcostamnt = @costamnt + @costamntins

  update ICStockDetail
  set 	ResvAmnt2 = @sumcostamnt
  from	ICStockDetail
  where (ICStockDetail.GoodID = @goodid) and 
	(ICStockDetail.BrchID = @brchid) and 
	(ICStockDetail.DocuType= @docutype) and 
	(ICStockDetail.DocuTypeCode = @docutypecode) and 
	(ICStockDetail.DocuID = @docuid) and
	(ICStockDetail.ListNo = @listno) and
	(ICStockDetail.StockDetailID = @StockDetailID)

  end

  return
error:
    raiserror(@errmsg, 16, 1)
    rollback transaction
end

GO
PRINT 'fixed dbo.tI_ICStockCost_ex';
GO

