 ALTER TRIGGER tI_ICStockDetail_ex on ICStockDetail          
  for INSERT          
  as          
begin          
  declare  @numrows int,          
           @nullcnt int,
           @validcnt int,          
           @insStockDetailID u_ID,          
           @errno   int,          
           @errmsg  varchar(255),          
    @cosflag varchar(20),          
    @havebrch int ,        
    @count int            
      
-- [Ane:25/08/2551][W20080807-004=>ปรับการ upate ICstock ออกเพราะทำให้การ delete , update icstockdetail ตอนที่บันทึกรายการและคำนวณต้นทุนช้าถ้าเบสที่มีขนาดใหญ่มากๆ]      
select @numrows = @@rowcount            
-- Option การคำนวณแยกตามคลัง(@cosflag = Y)หรือรวมคลัง(@cosflag = N)            
set @cosflag = (select top 1 ICOption.CostInveFlag From ICOption,inserted Where ICOption.BrchID =inserted.brchid)      
-- Option สาขาของ IC ว่าเป็นรวม(@havebrch = 0)หรือแยกสาขา(@havebrch = สาขาที่ทำการ)            
set @havebrch = (Select  top 1 (case when EmOptionEXT.havebrch = 'N'then 0 else inserted.Brchid end )From EmOptionEXT,inserted Where EmOptionEXT.systemid =( Select smsystem.systemid from smsystem where smsystem.systemcode ='IC' ) And EmOptionEXT.brchid = inserted.brchid )      
      
-- นับจำนวนของเอกสารรายการโอน โดยระบุว่าเป็นรายการโอนหรือไม่ในส่วนของ in          
select @count = count(ICStockDetail.stockdetailid)     
from  ICStockDetail , inserted        
where(ICStockDetail.GoodID = inserted.GoodID )      
and  ICStockDetail.docutype in (109,704,710,719,720,2001)     
and  (ICStockDetail.Brchid = @havebrch or 0 = @havebrch )      
and  (ICStockDetail.DocuDate >= inserted.DocuDate )      
      
 IF(@cosflag = 'N')          
   Begin          
     if (update(goodid)) and update(costflag) and update(goodstockqty) and update(goodamnt)          
     begin          
      update  ICStockDetail          
      set     ICStockDetail.CostFlag = 'N'          
      from    ICStockDetail,inserted          
      where  (ICStockDetail.GoodID = inserted.GoodID)           
       and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )            
       and(ICStockDetail.DocuDate >= inserted.DocuDate)           
       and(ICStockDetail.CostFlag = 'Y')           
       and(ICStockDetail.StockDetailID <> inserted.StockDetailID)          
             
      delete ICCostDetail          
      from   ICCostDetail,inserted          
      where (ICCostDetail.GoodID = inserted.GoodID)            
	  and (ICCostDetail.Brchid = @havebrch or 0 = @havebrch )        
      and (ICCostDetail.DocuDate >= inserted.DocuDate)          
     end    
   End    
 Else          
   Begin          
    IF(@count > 0)          
     -- เป็นการโอนรายการสินค้า           
     -- การทำงานของการคำนวณแยกตามคลัง  กรณีโอนสินค้า ตัดส่วนของการทำงานของ invetory ออกไป          
     begin        
       if (update(goodid)) and update(costflag) and update(goodstockqty) and update(goodamnt)          
       begin          
          update  ICStockDetail          
          set     ICStockDetail.CostFlag = 'N'          
          from    ICStockDetail,inserted          
          where  (ICStockDetail.GoodID = inserted.GoodID)           
           and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )            
           and(ICStockDetail.DocuDate >= inserted.DocuDate)           
           and(ICStockDetail.CostFlag = 'Y')           
           and(ICStockDetail.StockDetailID <> inserted.StockDetailID)          
                 
          delete  ICCostDetail          
          from    ICCostDetail,inserted          
          where  (ICCostDetail.GoodID = inserted.GoodID)            
			 and(ICCostDetail.Brchid = @havebrch or 0 = @havebrch )     
             and(ICCostDetail.DocuDate >= inserted.DocuDate)          
       end    
      end    
    else        
     --รายการอื่นที่ไม่ใช่โอนสินค้า        
     begin        
       if (update(goodid)) and update(costflag) and update(goodstockqty) and update(goodamnt)          
       begin          
          update  ICStockDetail          
          set     ICStockDetail.CostFlag = 'N'          
          from    ICStockDetail,inserted          
          where  (ICStockDetail.GoodID = inserted.GoodID)           
           and(ICStockDetail.Brchid = @havebrch or 0 = @havebrch )            
           and(ICStockDetail.DocuDate >= inserted.DocuDate)           
           and(ICStockDetail.CostFlag = 'Y')           
           and(ICStockDetail.StockDetailID <> inserted.StockDetailID)       
           and(ICStockDetail.InveID = inserted.InveID)      
                 
          delete  ICCostDetail          
          from    ICCostDetail,inserted          
          where  (ICCostDetail.GoodID = inserted.GoodID)            
              and(ICCostDetail.Brchid = @havebrch or 0 = @havebrch )          
              and(ICCostDetail.DocuDate >= inserted.DocuDate)      
              and(ICCostDetail.InveID = inserted.InveID)              
       end    
     end    
 End    
  return          
error:          
    raiserror(@errmsg, 16, 1)          
    rollback transaction          
end

GO
PRINT 'fixed dbo.tI_ICStockDetail_ex';
GO

