  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
  /* ERwin Builtin Sat Aug 10 10:56:21 2002 */
  /* EMLoca R/1112 ICStockTransfer ON CHILD INSERT RESTRICT */
  if
    /* %ChildFK(" or",update) */
    update(DestLocaID) or
    update(DestInveID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMLoca
        where
          /* %JoinFKPK(inserted,EMLoca) */
          inserted.DestLocaID = EMLoca.LocaID and
          inserted.DestInveID = EMLoca.InveID
