      select @errno  = 30002,
             @errmsg = 'Cannot INSERT ICStockTransfer because EMGoodUnit does not exist.'
      goto error
    end
  end

  /* ERwin Builtin Sat Aug 10 10:56:21 2002 */
  /* EMGoodUnit  ICStockTransfer ON CHILD INSERT RESTRICT */
  if
    /* %ChildFK(" or",update) */
    update(GoodStockUnitID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMGoodUnit
        where
