ALTER TRIGGER [dbo].[tI_WHStockSerialDetail_ex] on [dbo].[WHStockSerialDetail] For Insert AS
Begin        
  Declare @errmsg   varchar(255),        
  @errno    int,        
  @StockSerialDetailID u_id,        
  @goodid u_id ,    
  @lotno u_GoodCode,    
  @serialno u_GoodCode,
  @refflag u_Flag ,
  @prevdetailid  u_id ,
  @olddetailid u_id ,
  @docutype u_globalflag ,
  @refdocutype u_globalflag ,
  @flag int

Select @StockSerialDetailID = StockSerialDetailID ,      
	@docutype = DocuType ,
	@goodid = GoodID ,    
	@lotno  = LotNo ,
	@serialno = SerialNo ,
	@refflag = RefFlag
From Inserted    

IF @docutype in (1701,1702,1703,1704,1705,1706,1707,1708,1709,1710,1711,1713,1716) OR (@docutype = 1712 and @refflag <> 'D')
Begin   

	Update ICStockSerial Set        
		ICStockSerial.whDocuType  =Inserted.DocuType,        
		ICStockSerial.whDocuID  =Inserted.DocuID,        
		ICStockSerial.whListNo  =Inserted.ListNo,     
		ICStockSerial.whPrevDetailID =ICStockSerial.whStockSerialDetailID,
		ICStockSerial.whLastserialflag= (Case When Inserted.RefFlag = 'D' Then  'N' Else ICStockSerial.whSerialFlag End) ,    
		ICStockSerial.whSerialFlag = (Case When Inserted.RefFlag = 'D' Then  'R' Else isnull(Inserted.SerialFlag,'N') End) ,      
		ICStockSerial.whlistnoref  =Inserted.Seriallistno,        
		ICStockSerial.whInveID  =Inserted.InveID,        
		ICStockSerial.whLocaID  =Inserted.LocaID,
		ICStockSerial.whBrchID  =Inserted.BrchID,       
		ICStockSerial.whStockSerialDetailID=Inserted.StockSerialDetailID        
	From ICStockSerial,Inserted    
	Where Inserted.Stockserialdetailid =@stockserialdetailid    
	and ICStockSerial.GoodID=Inserted.GoodID        
	and ICStockSerial.LotNo=Inserted.LotNo        
	and ICStockSerial.SerialNo=Inserted.SerialNo        
	and inserted.refflag Not in ('U')

	Select @flag = isnull(Count(WHstockserialdetail.flag),0)
	From WHstockserialdetail
	Where isnull(WHstockserialdetail.flag,0) = 1  
	and WHstockserialdetail.goodid =@goodid  
	and WHstockserialdetail.lotno =@lotno  
	and WHstockserialdetail.serialno =@serialno
	and isnull(WHstockserialdetail.prevdetailid,0) = 0
	
	IF @flag > 0 
	Begin
		Update WHstockserialdetail Set
			WHstockserialdetail.Prevdetailid = @StockSerialDetailID ,
			WHstockserialdetail.flag = null
		Where isnull(WHstockserialdetail.flag,0) = 1  
		and WHstockserialdetail.goodid =@goodid  
		and WHstockserialdetail.lotno =@lotno  
		and WHstockserialdetail.serialno =@serialno
		and isnull(WHstockserialdetail.prevdetailid,0) = 0
		
		Update ICstockserial Set  
			ICstockserial.whPrevdetailid = WHstockserialdetail.Prevdetailid  
		from ICstockserial , WHstockserialdetail  
		Where ICstockserial.goodid =@goodid  
		and ICstockserial.lotno =@lotno  
		and ICstockserial.serialno =@serialno  
		and ICstockserial.whstockserialdetailid = WHstockserialdetail.Stockserialdetailid  
		and isnull(ICstockserial.whPrevdetailid,0) <> WHstockserialdetail.Prevdetailid
	End
End


IF @docutype = 1712 and @refflag = 'D'
Begin
	Set @refdocutype = 1711
	/*Set Stockflag ของเอกสารต้นขั้วที่อ้างอิงมาทำรายการให้เป็นไม่มีผลต่อ Stock เพื่อไม่ให้มีผลต่อการแสดงที่รายงานเคลื่อนไหว Serial*/			
	/*update stockflag ของสั่งจองให้เป็น 0(ไม่มีผลต่อสต็อค) เพื่อจะได้คืนสถานะก่อนหน้าไปอีก 1 ระดับ*/
	Select @prevdetailid  = WHstockserialdetail.Prevdetailid
	From WHstockserialdetail , Inserted
	Where WHstockserialdetail.stockserialdetailid = Inserted.stockserialdetailid	

	/*หาเลขที่ก่อนหน้าอีก 1 ระดับ เช่น ไม่อนุมัติใบขอเบิก ก็ต้องหา prevdetail ของใบขอเบิกว่าสถานะ R นั้นมาจากเอกสารอะไร*/
	set @olddetailid = (Select S.Prevdetailid 
	From WHstockserialdetail S
	Where S.Stockserialdetailid =@prevdetailid
	and S.docutype =@refdocutype)

	Update ICStockSerial Set
		ICStockSerial.whDocuType     =WHstockserialdetail.DocuType,    
		ICStockSerial.whDocuID       =WHstockserialdetail.DocuID,      
		ICStockSerial.whListNo       =WHstockserialdetail.ListNo,   
		ICStockSerial.whPrevDetailID =WHstockserialdetail.Prevdetailid,  
		ICStockSerial.whLastserialflag= isnull((select WH.Serialflag From WHstockserialdetail WH where WH.stockSerialDetailid = WHstockserialdetail.Prevdetailid),'N'),  
		ICStockSerial.whSerialFlag   =isnull(WHstockserialdetail.SerialFlag,'N'),    
		ICStockSerial.whListNoRef    =WHstockserialdetail.Seriallistno,      
		ICStockSerial.whInveID       =WHstockserialdetail.InveID,      
		ICStockSerial.whLocaID       =WHstockserialdetail.LocaID,
		ICStockSerial.whBrchID       = WHstockserialdetail.BrchID,      
		ICStockSerial.whStockSerialDetailID=WHstockserialdetail.StockSerialDetailID      
	from ICStockSerial,WHstockserialdetail  
	where WHstockserialdetail.StockSerialDetailID = @olddetailid
	and ICStockSerial.GoodID=WHstockserialdetail.GoodID      
	and ICStockSerial.LotNo=WHstockserialdetail.LotNo      
	and ICStockSerial.SerialNo=WHstockserialdetail.SerialNo	
	and ICstockserial.whstockserialdetailid = @prevdetailid
End

Return
         
error:        
    raiserror(@errmsg, 16, 1)        
    rollback transaction        
End

GO
PRINT 'fixed dbo.tI_WHStockSerialDetail_ex';
GO

