ALTER TRIGGER tU_BankNetDT on BankNetDT    
  for INSERT    
  as    
/*  
    Create By Pawanrad Phiaphab(mas) on 2006-12-26  
    Update trigger on BankNetDT        
    Default body for tU_BankNetDT    */  
/*
    Modify By Sudawan Sukwanarom on 2008-11-27
    Desc. : Don't Check Exist With Table AppayDT,Effect with clear data AP System.
*/
begin    
  declare  @numrows int,    
           @nullcnt int,    
           @validcnt int,    
           @insExportID u_ID,     
           @insListNo u_ListNo,   
           @errno   int,    
           @errmsg  varchar(255)    
    
  select @numrows = @@rowcount    
  /* BankNetHD : BankNetDT ON CHILD INSERT RESTRICT */    
  if    
    update(ExportID)    
