       from inserted,EMVendor    
 /* %JoinFKPK(inserted,EMVendor) */    
        where inserted.VendorID = EMVendor.VendorID    
    select @nullcnt = count(*) from inserted where inserted.VendorID is null    
    if @validcnt + @nullcnt != @numrows    
    begin    
      select @errno  = 30002,    
             @errmsg = 'Cannot UPDATE BankNetDT because EMVendor does not exist.'    
      goto error    
    end    
