    select @nullcnt = 0    
    select @validcnt = count(*)    
       from inserted,CQBookMove    
 /* %JoinFKPK(inserted,CQBookMove) */    
        where inserted.BookMoveID = CQBookMove.BookMoveID    
    select @nullcnt = count(*) from inserted where inserted.BookMoveID is null    
    if @validcnt + @nullcnt != @numrows    
    begin    
      select @errno  = 30002,    
             @errmsg = 'Cannot UPDATE BankNetDT because CQBookMove does not exist.'    
      goto error    
    end    
  end    

  /* EMBank : BankNetDT ON CHILD INSERT RESTRICT */    
  if    
    update(BankID)    
  begin    
    select @nullcnt = 0    
    select @validcnt = count(*)    
       from inserted,EMBank where inserted.BankID = EMBank.BankID    
    select @nullcnt = count(*)   
 from inserted where inserted.BankID is null  
    if @validcnt + @nullcnt != @numrows    
    begin    
      select @errno  = 30002,    
             @errmsg = 'Cannot UPDATE BankNetDT because EMBank does not exist.'    
      goto error    
    end    
  end    
  
  /* SMSat : BankNetDT ON CHILD INSERT RESTRICT */    
  /* PostID */   
  if    
    update(PostID)    
  begin    
    select @nullcnt = 0    
    select @validcnt = count(*)    
       from inserted,SMSat where inserted.PostID = SMSat.GlobalID    
    select @nullcnt = count(*)   
 from inserted where inserted.PostID is null    
    if @validcnt + @nullcnt != @numrows    
    begin    
      select @errno  = 30002,    
             @errmsg = 'Cannot UPDATE BankNetDT because SMSat does not exist.'    
      goto error    
    end    
  end    
  
  /* EMBrch : BankNetDT ON CHILD INSERT RESTRICT */    
  if    
    update(BrchID)    
  begin    
    select @nullcnt = 0    
    select @validcnt = count(*)    
    from inserted,EMBrch where inserted.BrchID = EMBrch.BrchID    
    select @nullcnt = count(*)   
 from inserted where inserted.BrchID is null    
    if @validcnt + @nullcnt != @numrows    
    begin    
      select @errno  = 30002,    
             @errmsg = 'Cannot UPDATE BankNetDT because EMBrch does not exist.'    
      goto error    
    end    
  end    
  
  return  
  
error:    
