ALTER TRIGGER tU_EMAccAlloc on EMAccAlloc
  for UPDATE
  as
/* ERwin Builtin Wed Sep 11 14:14:09 2002 */
/* UPDATE trigger on EMAccAlloc */
/* default body for tU_EMAccAlloc */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insListNo u_ListNo, 
           @insAccID u_ID,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
/* ERwin Builtin Wed Sep 11 14:14:09 2002 */
  /* EMDept R/1230 EMAccAlloc ON CHILD UPDATE RESTRICT */
  if
    /* ChildFK(" or",update) */
    update(DeptID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMDept
        where
          /* JoinFKPK */
          inserted.DeptID = EMDept.DeptID
    /* NotnullFK */
    select @nullcnt = count(*) from inserted where
      inserted.DeptID is null
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30007,
             @errmsg = 'Cannot UPDATE EMAccAlloc because EMDept does not exist.'
      goto error
    end
  end

/* ERwin Builtin Wed Sep 11 14:14:09 2002 */
  /* EMAcc R/1229 EMAccAlloc ON CHILD UPDATE RESTRICT */
  if
    /* ChildFK(" or",update) */
    update(AccID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMAcc
        where
          /* JoinFKPK */
          inserted.AccID = EMAcc.AccID
    /* NotnullFK */
    
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30007,
             @errmsg = 'Cannot UPDATE EMAccAlloc because EMAcc does not exist.'
      goto error
    end
  end



  return
error:
    raiserror(@errmsg, 16, 1)
    rollback transaction
end

