ALTER TRIGGER tU_EMCreditDeptHD on EMCreditDeptHD
  for UPDATE
  as
/* ERwin Builtin Wed Sep 18 11:25:41 2002 */
/* UPDATE trigger on EMCreditDeptHD */
/* default body for tU_EMCreditDeptHD */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insCreditDeptID u_ID,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
/* ERwin Builtin Wed Sep 18 11:25:41 2002 */
  /* EMDept R/1229 EMCreditDeptHD ON CHILD UPDATE RESTRICT */
  if
    /* ChildFK(" or",update) */
    update(DeptID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMDept
        where
          /* JoinFKPK */
          inserted.DeptID = EMDept.DeptID
    /* NotnullFK */
    select @nullcnt = count(*) from inserted where
      inserted.DeptID is null
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30007,
             @errmsg = 'Cannot UPDATE EMCreditDeptHD because EMDept does not exist.'
      goto error
    end
  end


/* ERwin Builtin Wed Sep 18 11:25:41 2002 */
  /* EMCreditDeptHD R/1234 EMCreditDeptCust ON PARENT UPDATE CASCADE */
  if
    /* (" or",update) */
    update(CreditDeptID)
  begin
    if @numrows = 1
    begin
      select @insCreditDeptID = inserted.CreditDeptID
        from inserted
      update EMCreditDeptCust
      set
        /*  JoinFKPK" = ",",") */
        EMCreditDeptCust.CreditDeptID = @insCreditDeptID
      from EMCreditDeptCust,inserted,deleted
      where
        /*  JoinFKPK" = "," and") */
        EMCreditDeptCust.CreditDeptID = deleted.CreditDeptID
    end
    else
    begin
      select @errno = 30006,
             @errmsg = 'Cannot cascade EMCreditDeptHD UPDATE because more than one row has been affected.'
      goto error
    end
  end

/* ERwin Builtin Wed Sep 18 11:25:41 2002 */
  /* EMCreditDeptHD R/1233 EmCreditCustGroup ON PARENT UPDATE CASCADE */
  if
    /* (" or",update) */
    update(CreditDeptID)
  begin
    if @numrows = 1
    begin
      select @insCreditDeptID = inserted.CreditDeptID
        from inserted
      update EmCreditCustGroup
      set
        /*  JoinFKPK" = ",",") */
        EmCreditCustGroup.CreditDeptID = @insCreditDeptID
      from EmCreditCustGroup,inserted,deleted
      where
        /*  JoinFKPK" = "," and") */
        EmCreditCustGroup.CreditDeptID = deleted.CreditDeptID
    end
    else
    begin
      select @errno = 30006,
             @errmsg = 'Cannot cascade EMCreditDeptHD UPDATE because more than one row has been affected.'
      goto error
    end
  end


  return
error:
    raiserror(@errmsg, 16, 1)
    rollback transaction
end

