ALTER TRIGGER tU_EMCustClient on EMCustClient for UPDATE as
/* ERwin Builtin Mon Feb 11 13:39:15 2002 */
/* UPDATE trigger on EMCustClient */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insCustID u_ID, 
           @insListNo u_ListNo,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
  /* ERwin Builtin Mon Feb 11 13:39:15 2002 */
  /* EMCust R/195 EMCustClient ON CHILD UPDATE RESTRICT */
  if
    /* %ChildFK(" or",update) */
    update(CustID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMCust
        where
          /* %JoinFKPK(inserted,EMCust) */
