ALTER TRIGGER tU_EMVendorContact on EMVendorContact
  for UPDATE
  as
/* ERwin Builtin Wed Sep 11 17:25:01 2002 */
/* UPDATE trigger on EMVendorContact */
begin
  declare  @numrows int,
           @nullcnt int,
           @validcnt int,
           @insContactID u_ID,
           @errno   int,
           @errmsg  varchar(255)

  select @numrows = @@rowcount
  /* ERwin Builtin Wed Sep 11 17:25:01 2002 */
  /* EMVendor R/1172 EMVendorContact ON CHILD UPDATE RESTRICT */
  if
    /* %ChildFK(" or",update) */
    update(VendorID)
  begin
    select @nullcnt = 0
    select @validcnt = count(*)
      from inserted,EMVendor
        where
          /* %JoinFKPK(inserted,EMVendor) */
          inserted.VendorID = EMVendor.VendorID
    /* %NotnullFK(inserted," is null","select @nullcnt = count(*) from inserted where"," and") */
    
    if @validcnt + @nullcnt != @numrows
    begin
      select @errno  = 30007,
             @errmsg = 'Cannot UPDATE EMVendorContact because EMVendor does not exist.'
      goto error
    end
  end


  /* ERwin Builtin Wed Sep 11 17:25:01 2002 */
  return
error:
    raiserror(@errmsg, 16, 1)
    rollback transaction
end

GO
